# ── Per-framework knowledge-base enrichment ──────────────────────────────
# Optional *_knowledge.json files (nist_knowledge.json, and future soc2/dpdp/
# bcms/xbom/iso27001/vapt ones) add auditor sub-questions per control, keyed
# by the control's use_case ID (e.g. "GV.OC"). Merged into prompt_hint at
# import time so audit_graph.py's existing expected_evidence/prompt_hint
# plumbing (-> audit_chains.py's {expected_evidence} template variable) picks
# them up with no changes to the generation pipeline itself. Missing/invalid
# knowledge files are non-fatal -- controls just run without the extra
# sub-questions, same as before this enrichment existed.
def _merge_knowledge_base(use_cases, json_filename):
    import json
    import os
    path = os.path.join(os.path.dirname(__file__), "knowledge", json_filename)
    try:
        with open(path, "r", encoding="utf-8") as f:
            knowledge = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        return
    for uc in use_cases:
        control_code = str(uc.get("use_case", "")).split(" ")[0]
        entry = knowledge.get(control_code)
        if not entry:
            continue
        sub_qs = entry.get("sub_questions") or []
        remediation = entry.get("remediation_guidance") or ""
        # Idempotency guard: this module runs at import time, and some tooling (scripts,
        # REPLs, certain reload paths) can import it more than once in the same process.
        # Without this check a second merge pass would append a second "Sub-questions to
        # verify" block on top of the first, growing without bound.
        if sub_qs and "Sub-questions to verify:" not in uc.get("prompt_hint", ""):
            questions_block = " ".join(f"({i+1}) {q}" for i, q in enumerate(sub_qs))
            uc["prompt_hint"] = f"{uc.get('prompt_hint', '')} Sub-questions to verify: {questions_block}"
        if remediation and remediation not in uc.get("recommendation", ""):
            uc["recommendation"] = f"{uc.get('recommendation', '')} {remediation}"


_merge_knowledge_base(USE_CASES, "nist_knowledge.json")
